import re

PATTERNS = {
    "EMAIL": re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+"),
    "PHONE": re.compile(r"\b\d{3}[-.\s]?\d{3}[-.\s]?\d{4}\b"),
}

def redact_pii(text: str) -> str:
    for label, rx in PATTERNS.items():
        text = rx.sub(f"[{label}]", text)     # replace with typed placeholder
    return text

print(redact_pii("Call ada@example.com or 555-123-4567"))
# 'Call [EMAIL] or [PHONE]'

# request the minimum scope for the job
def make_client(task: str):
    if task == "read_reports":
        return Client(scope="reports:read")        # read-only, one resource
    if task == "issue_refund":
        return Client(scope="payments:refund", ttl=300)  # narrow + short-lived
    raise ValueError("no key scope for this task")
# a leaked read-only, 5-min token is far less dangerous than an admin key
